 const studios=[{id:'home',name:'Maquette maison',cost:0,quality:1},{id:'independent',name:'Studio indépendant',cost:750,quality:1.02},{id:'professional',name:'Studio professionnel',cost:2500,quality:1.06},{id:'premium',name:'Studio premium',cost:6000,quality:1.1}]
