 const current=chosen===null?null:labels[chosen],baseCut=current?Math.max(5,Math.min(38,current[3]-Math.round(leverage*.12))):20,baseAdvance=current?Math.round(current[4]*(.55+leverage/100)):0,baseMarketing=current?Math.round(current[5]*(.55+leverage/90)):0
 const toggle=(x:string)=>setTypes(old=>old.includes(x)?old.filter(v=>v!==x):[...old,x]),toggleTerritory=(x:string)=>setTerritories(old=>old.includes(x)?old.filter(v=>v!==x):[...old,x])
 function begin(i:number){const l=labels[i];setChosen(i);setStage(1);setDeal('Recording deal');setYears(3);setProjects(2);setArtistRoyalty(100-Math.max(5,Math.min(38,l[3]-Math.round(leverage*.12))));setAdvance(Math.round(l[4]*(.55+leverage/100)));setMarketing(Math.round(l[5]*(.55+leverage/90)));setRecording(Math.round(l[4]*.65));setTypes(['Album studio','EP']);setMasters(leverage>=72?'artist':leverage>=38?'shared':'label');setMasterShare(leverage>=72?100:leverage>=38?55:0);setDistribution(Math.max(8,22-Math.round(leverage*.08)));setTerritories(['Monde']);setExclusive(true);setCreative(Math.min(95,25+leverage*.65));setThreeSixty(0);setMerchShare(0);setLiveShare(0);setRecoupMarketing(50);setTerminationFee(0)}
 function counter(){if(chosen===null||!current)return;if(!types.length||!territories.length){notify('Choisissez au moins un format et un territoire.');return}
  const cost=Math.max(0,artistRoyalty-(100-baseCut))*.65+Math.max(0,advance-baseAdvance)/Math.max(1,baseAdvance)*9+Math.max(0,marketing-baseMarketing)/Math.max(1,baseMarketing)*5+Math.max(0,recording-current[4]*.65)/Math.max(1,current[4])*4+(masters==='artist'?(leverage<35?28:leverage<55?16:leverage<72?7:0):masters==='shared'?(leverage<20?12:leverage<40?5:0):0)+Math.max(0,creative-(25+leverage*.65))*.22+Math.max(0,threeSixty-5)*.25+Math.max(0,merchShare-5)*.15+Math.max(0,liveShare-5)*.15
  const tolerance=8+leverage*.42+(current[1]==='Indépendant'?5:0);if(cost>tolerance){notify('Contre-proposition refusée par '+current[0]+'. Ajustez certaines clauses et réessayez : la semaine ne change pas.');return}setStage(3);notify(current[0]+' accepte votre contre-proposition. Vous pouvez signer cette semaine.')
 }
 function sign(){if(chosen===null||!current)return;const recoupable=advance+recording+marketing*recoupMarketing/100;const contract:LabelContract={id:uid(),label:current[0],years,projects,remainingProjects:projects,remainingWeeks:years*52,types,royalty:100-artistRoyalty,artistRoyalty,advance,marketing,recordingBudget:recording,recoupableBalance:recoupable,masterOwnership:masters,artistMasterShare:masters==='artist'||masters==='license'?100:masters==='shared'?masterShare:0,distributionFee:distribution,territories,exclusive,creativeControl:creative,threeSixtyShare:threeSixty,merchShare,liveShare,terminationFee,signedWeek:artist.week,signedYear:artist.year,status:'active'}
  update({label:current[0],labelShare:100-artistRoyalty,money:artist.money+advance,campaigns:[...(artist.campaigns??[]),{id:uid(),name:'Soutien marketing · '+current[0],remainingWeeks:3,multiplier:1+Math.min(.4,marketing/500000)}],contracts:[...history,contract],posts:[{id:uid(),week:artist.week,year:artist.year,source:'Music News',text:artist.name+' signe un '+deal.toLowerCase()+' avec '+current[0]+'.'},...artist.posts]});setChosen(null);setStage(0);notify('Contrat signé avec '+current[0]+'. Avance versée : '+euro(advance)+'. Toutes les étapes ont eu lieu pendant la semaine '+artist.week+'.')}
