 function signTalent(t:typeof prospects[number]){if(!artist.ownLabelName){notify('Créez d’abord votre maison de disques.');return}if(roster.some(a=>a.id===t.id)){notify('Cet artiste est déjà dans votre catalogue.');return}const cost=talentAdvance+3000;if((artist.ownLabelCapital??0)<cost){notify('Capital insuffisant : '+euro(cost)+' nécessaires pour signer cet artiste.');return}update({ownLabelCapital:(artist.ownLabelCapital??0)-cost,ownLabelArtists:[...roster,{...t,artistRoyalty:talentRoyalty,advance:talentAdvance,remainingWeeks:156,streams:0,revenue:0}],ownLabelReputation:Math.min(100,(artist.ownLabelReputation??10)+2)});notify(t.name+' rejoint '+artist.ownLabelName+'. Contrat de trois ans signé.')}
